 s.photos=[{...newItem('photos',s),id:'station',src:'/assets/station.svg',trigger:'display'},{...newItem('photos',s),id:'sea',src:'/assets/sea.svg',trigger:'zoom'},{...newItem('photos',s),id:'room',src:'/assets/room.svg',initial:false,trigger:'grid'}];s.recentOrder=['station','sea','room'];s.albums=[{...newItem('albums',s),id:'album_night',name:'밤의 기록',photoIds:['station','sea']},{...newItem('albums',s),id:'album_summer',name:'여름',photoIds:['sea','room']}];s.phone.cameraPhotoId='room';
