 s.sms=[{...newItem('sms',s),id:'sms1',sender:'북안역',text:'마지막 열차는 22:30에 출발합니다.'}];s.safari=[{...newItem('safari',s),id:'search_station',keyword:'북안역 막차',title:'마지막 열차 시간표',src:'/assets/station.svg'}];
